def apply_implementation_patch() -> None:
    session_path = "src/LatencyPilot.Benchmarking/Optimization/GpuAutoAffinitySession.cs"
    text = read(session_path)

    text = replace_once(
        text,
        "    private const double MaximumRunToRunPrimaryDrift = 0.05;\n",
        "",
        "remove max-min repeatability threshold")

    original_start = "            // Establish continuity once, then score the exact original state three\n"
    original_end = "            var screeningEvaluations = new List<CandidateEvaluation>(physicalCandidates.Length);\n"
    new_original = '''            // Establish continuity once, then collect enough exact-Original samples\n            // to identify three repeatable runs. A single noisy Windows/background\n            // outlier is replaced rather than aborting the whole search.\n            var referenceObservation = await CaptureAcceptedAsync(\n                () => ++nextRunNumber,\n                "screening-warmup",\n                GpuConfirmationOrder.Original,\n                null,\n                TransitionWarmupDuration,\n                reference: null,\n                experimentId: null,\n                trialReports,\n                cancellationToken).ConfigureAwait(false);\n            var reference = referenceObservation.Evidence;\n            var originalObservations = new List<GpuAutoAffinityTrialObservation>(\n                GpuRepeatabilityClusterSelector.MaximumAttemptCount);\n            var original = OriginalEvaluation.Unrankable(\n                "Original repeatability has not collected three scored observations yet.",\n                totalObservationCount: 0);\n            while (originalObservations.Count < GpuRepeatabilityClusterSelector.MaximumAttemptCount)\n            {\n                originalObservations.Add(await CaptureAcceptedAsync(\n                    () => ++nextRunNumber,\n                    "screening-original",\n                    GpuConfirmationOrder.Original,\n                    null,\n                    request.ScreeningDuration,\n                    reference,\n                    experimentId: null,\n                    trialReports,\n                    cancellationToken).ConfigureAwait(false));\n\n                if (originalObservations.Count < GpuRepeatabilityClusterSelector.RequiredRunCount)\n                {\n                    continue;\n                }\n\n                original = CreateOriginalEvaluation(originalObservations.ToArray());\n                if (original.IsRankable)\n                {\n                    break;\n                }\n            }\n\n            if (!original.IsRankable)\n            {\n                reasons.Add($"Original-state benchmark is not repeatable enough for an automatic Keep decision: {original.Reason}");\n                var originalVerified = await backend.VerifyOriginalStateAsync(CancellationToken.None).ConfigureAwait(false);\n                return CreateResult(\n                    request, startedAtUtc, GpuOptimizationRecommendation.RestoreOriginal, null,\n                    originalVerified, originalVerified, candidateReports, trialReports, reasons);\n            }\n            if (original.TotalObservationCount > original.ValidObservationCount)\n            {\n                reasons.Add(string.Create(\n                    System.Globalization.CultureInfo.InvariantCulture,\n                    $"Original repeatability recovered {original.ValidObservationCount} valid runs from {original.TotalObservationCount} attempts; {original.TotalObservationCount - original.ValidObservationCount} outlier sample(s) were excluded from ranking. Max valid 1%-low deviation from the cluster median was {original.PrimaryRelativeNoise:P2}."));\n            }\n\n'''
    text = replace_between(text, original_start, original_end, new_original + original_end, "adaptive Original sampling")

    rescreen_start = "    private async Task<IReadOnlyList<CandidateEvaluation>> RescreenTopCandidatesAsync(\n"
    rescreen_end = "    private async Task<GpuAutoAffinitySessionResult> VerifyAndKeepFinalistAsync(\n"
    new_rescreen = '''    private async Task<IReadOnlyList<CandidateEvaluation>> RescreenTopCandidatesAsync(\n        GpuAutoAffinitySessionRequest request,\n        IReadOnlyList<CandidateEvaluation> screeningEvaluations,\n        GpuBenchmarkEvidence reference,\n        List<GpuAutoAffinityCandidateReport> candidateReports,\n        List<GpuAutoAffinityTrialReport> trialReports,\n        Func<int> nextRunNumber,\n        CancellationToken cancellationToken)\n    {\n        var shortlist = CreateAdaptiveShortlist(screeningEvaluations);\n        if (shortlist.Length == 0)\n        {\n            return [];\n        }\n\n        // The screen contributes observation #1. Every finalist receives at least\n        // two fresh transition-isolated re-tests. Only finalists that still lack a\n        // stable 3-run cluster receive up to two adaptive replacement rounds.\n        var freshByProcessor = shortlist.ToDictionary(\n            static item => item.Candidate.Processor,\n            static _ => new List<GpuAutoAffinityTrialObservation>(capacity: 4));\n        var stableByProcessor = new Dictionary<LogicalProcessorId, CandidateEvaluation>();\n        var failureByProcessor = new Dictionary<LogicalProcessorId, string>();\n\n        for (var round = 0; round < GpuRepeatabilityClusterSelector.MaximumAttemptCount - 1; round++)\n        {\n            var roundCandidates = shortlist\n                .Where(item =>\n                    !failureByProcessor.ContainsKey(item.Candidate.Processor) &&\n                    !stableByProcessor.ContainsKey(item.Candidate.Processor))\n                .Select(static item => item.Candidate)\n                .ToArray();\n            if (roundCandidates.Length == 0)\n            {\n                break;\n            }\n\n            var roundSeed = unchecked(request.ShuffleSeed ^ (int)(0x9E3779B9u * (uint)(round + 1)));\n            ShuffleDeterministically(roundCandidates, roundSeed);\n\n            foreach (var candidate in roundCandidates)\n            {\n                cancellationToken.ThrowIfCancellationRequested();\n                try\n                {\n                    var fresh = await MeasureCandidateAsync(\n                        candidate,\n                        FinalistPhaseName,\n                        repetitions: 1,\n                        request.ScreeningDuration,\n                        reference,\n                        nextRunNumber,\n                        trialReports,\n                        cancellationToken).ConfigureAwait(false);\n                    freshByProcessor[candidate.Processor].AddRange(fresh);\n\n                    var screened = shortlist.Single(item => item.Candidate.Processor == candidate.Processor);\n                    var combined = screened.Observations\n                        .Concat(freshByProcessor[candidate.Processor])\n                        .ToArray();\n                    if (combined.Length >= GpuRepeatabilityClusterSelector.RequiredRunCount)\n                    {\n                        var evaluation = CreateEvaluation(candidate, combined);\n                        if (evaluation.IsRankable)\n                        {\n                            stableByProcessor[candidate.Processor] = evaluation;\n                        }\n                    }\n                }\n                catch (SessionAbortException abort)\n                {\n                    failureByProcessor[candidate.Processor] = abort.Message;\n                }\n            }\n        }\n\n        var finalists = new List<CandidateEvaluation>(shortlist.Length);\n        foreach (var screened in shortlist)\n        {\n            CandidateEvaluation evaluation;\n            if (failureByProcessor.TryGetValue(screened.Candidate.Processor, out var failure))\n            {\n                evaluation = CandidateEvaluation.Unrankable(\n                    screened.Candidate,\n                    failure,\n                    1 + freshByProcessor[screened.Candidate.Processor].Count);\n            }\n            else if (stableByProcessor.TryGetValue(screened.Candidate.Processor, out var stable))\n            {\n                evaluation = stable;\n            }\n            else\n            {\n                var combined = screened.Observations\n                    .Concat(freshByProcessor[screened.Candidate.Processor])\n                    .ToArray();\n                evaluation = CreateEvaluation(screened.Candidate, combined);\n            }\n\n            var report = ToReport(\n                FinalistPhaseName,\n                evaluation,\n                freshByProcessor[screened.Candidate.Processor].Count);\n            candidateReports.Add(report);\n            await PublishCandidateReportAsync(report).ConfigureAwait(false);\n            finalists.Add(evaluation);\n        }\n\n        return finalists;\n    }\n\n'''
    text = replace_between(text, rescreen_start, rescreen_end, new_rescreen + rescreen_end, "adaptive finalist resampling")

    eval_start = "    private static CandidateEvaluation CreateEvaluation(\n"
    eval_end = "    private static bool IsMeasurablyBetterThanOriginal(\n"
    new_eval = '''    private static CandidateEvaluation CreateEvaluation(\n        GpuAffinityCandidate candidate,\n        GpuAutoAffinityTrialObservation[] observations)\n    {\n        if (observations.Length == 0)\n        {\n            return CandidateEvaluation.Unrankable(candidate, "No scored benchmark observations were captured.", 0);\n        }\n\n        var stats = observations\n            .Select(static observation => GpuBenchmarkEvidenceInterpreter.Interpret(observation.Evidence).VideoStats)\n            .ToArray();\n        if (stats.Any(static item => item is null))\n        {\n            return CandidateEvaluation.Unrankable(\n                candidate,\n                "The controlled benchmark did not provide complete AVG / 1% low / 0.1% low frame-period statistics.",\n                observations.Length);\n        }\n\n        var values = stats.Select(static item => item!).ToArray();\n        if (!HasFiniteRankingStatistics(values))\n        {\n            return CandidateEvaluation.Unrankable(\n                candidate,\n                "Benchmark ranking statistics are missing or non-finite.",\n                observations.Length);\n        }\n\n        GpuBenchmarkVideoStats[] selectedValues;\n        GpuAutoAffinityTrialObservation[] selectedObservations;\n        double primaryRelativeNoise;\n        if (observations.Length == 1)\n        {\n            selectedValues = values;\n            selectedObservations = observations;\n            primaryRelativeNoise = 0d;\n        }\n        else\n        {\n            var cluster = GpuRepeatabilityClusterSelector.Select(\n                values.Select(static item => item.Low1PctFps).ToArray());\n            if (cluster is null)\n            {\n                return CandidateEvaluation.Unrankable(\n                    candidate,\n                    BuildNoStableClusterReason(observations.Length),\n                    observations.Length);\n            }\n\n            selectedValues = cluster.Indexes.Select(index => values[index]).ToArray();\n            selectedObservations = cluster.Indexes.Select(index => observations[index]).ToArray();\n            primaryRelativeNoise = cluster.MaximumRelativeDeviation;\n        }\n\n        return new CandidateEvaluation(\n            candidate,\n            selectedObservations,\n            Median(selectedValues.Select(static item => item.Low1PctFps)),\n            Median(selectedValues.Select(static item => item.Low01PctFps)),\n            Median(selectedValues.Select(static item => item.AvgFps)),\n            Median(selectedValues.Select(static item => item.P99Milliseconds)),\n            primaryRelativeNoise,\n            selectedObservations.Length,\n            observations.Length,\n            IsRankable: true,\n            Reason: null);\n    }\n\n    private static OriginalEvaluation CreateOriginalEvaluation(\n        GpuAutoAffinityTrialObservation[] observations)\n    {\n        if (observations.Length == 0)\n        {\n            return OriginalEvaluation.Unrankable("No scored Original observations were captured.", 0);\n        }\n\n        var stats = observations\n            .Select(static observation => GpuBenchmarkEvidenceInterpreter.Interpret(observation.Evidence).VideoStats)\n            .ToArray();\n        if (stats.Any(static item => item is null))\n        {\n            return OriginalEvaluation.Unrankable(\n                "Original benchmark lacks complete frame-period statistics.",\n                observations.Length);\n        }\n\n        var values = stats.Select(static item => item!).ToArray();\n        if (!HasFiniteRankingStatistics(values))\n        {\n            return OriginalEvaluation.Unrankable(\n                "Original benchmark ranking statistics are missing or non-finite.",\n                observations.Length);\n        }\n\n        var cluster = GpuRepeatabilityClusterSelector.Select(\n            values.Select(static item => item.Low1PctFps).ToArray());\n        if (cluster is null)\n        {\n            return OriginalEvaluation.Unrankable(\n                BuildNoStableClusterReason(observations.Length),\n                observations.Length);\n        }\n\n        var selected = cluster.Indexes.Select(index => values[index]).ToArray();\n        return new OriginalEvaluation(\n            Median(selected.Select(static item => item.Low1PctFps)),\n            Median(selected.Select(static item => item.Low01PctFps)),\n            Median(selected.Select(static item => item.AvgFps)),\n            Median(selected.Select(static item => item.P99Milliseconds)),\n            cluster.MaximumRelativeDeviation,\n            cluster.Indexes.Length,\n            observations.Length,\n            true,\n            null);\n    }\n\n    private static bool HasFiniteRankingStatistics(IEnumerable<GpuBenchmarkVideoStats> values) =>\n        values.All(static item =>\n            double.IsFinite(item.Low1PctFps) && item.Low1PctFps > 0 &&\n            double.IsFinite(item.Low01PctFps) && item.Low01PctFps > 0 &&\n            double.IsFinite(item.AvgFps) && item.AvgFps > 0 &&\n            double.IsFinite(item.P99Milliseconds) && item.P99Milliseconds > 0);\n\n    private static string BuildNoStableClusterReason(int observationCount) =>\n        string.Create(\n            System.Globalization.CultureInfo.InvariantCulture,\n            $"No stable {GpuRepeatabilityClusterSelector.RequiredRunCount}-run 1% low cluster exists within ±{GpuRepeatabilityClusterSelector.RelativeTolerance:P0} after {observationCount} scored observation(s)." );\n\n'''
    text = replace_between(text, eval_start, eval_end, new_eval + eval_end, "robust repeatability evaluation")

    text = text.replace("original.PrimaryRelativeSpread", "original.PrimaryRelativeNoise")
    text = text.replace("candidate.PrimaryRelativeSpread", "candidate.PrimaryRelativeNoise")

    report_start = "    private static GpuAutoAffinityCandidateReport ToReport(\n"
    report_end = "    private static GpuAutoAffinityTrialReport ToTrialReport(\n"
    new_report = '''    private static GpuAutoAffinityCandidateReport ToReport(\n        string phase,\n        CandidateEvaluation evaluation,\n        int trialCount) =>\n        new(\n            phase,\n            evaluation.Candidate.PhysicalCoreIndex,\n            evaluation.Candidate.Processor,\n            trialCount,\n            evaluation.IsRankable ? "Ranked" : "Inconclusive",\n            RelativeFrameP99Improvement: null,\n            RegressedGuardrails: [],\n            evaluation.IsRankable\n                ? evaluation.TotalObservationCount >= GpuRepeatabilityClusterSelector.RequiredRunCount\n                    ? string.Create(\n                        System.Globalization.CultureInfo.InvariantCulture,\n                        $"Stable 1%-low cluster {evaluation.ValidObservationCount}/{evaluation.TotalObservationCount}; max median-centered deviation {evaluation.PrimaryRelativeNoise:P2}. Median 1% low {evaluation.MedianLow1Fps:F1} FPS; AVG {evaluation.MedianAvgFps:F1} FPS; p99 {evaluation.MedianFrameP99Milliseconds:F2} ms; 0.1% low {evaluation.MedianLow01Fps:F1} FPS (rare-tail context).")\n                    : string.Create(\n                        System.Globalization.CultureInfo.InvariantCulture,\n                        $"Single-pass screen. 1% low {evaluation.MedianLow1Fps:F1} FPS; AVG {evaluation.MedianAvgFps:F1} FPS; p99 {evaluation.MedianFrameP99Milliseconds:F2} ms; 0.1% low {evaluation.MedianLow01Fps:F1} FPS (rare-tail context).")\n                : evaluation.Reason);\n\n'''
    text = replace_between(text, report_start, report_end, new_report + report_end, "candidate report repeatability summary")

    old_records = '''    private sealed record CandidateEvaluation(\n        GpuAffinityCandidate Candidate,\n        GpuAutoAffinityTrialObservation[] Observations,\n        double MedianLow1Fps,\n        double MedianLow01Fps,\n        double MedianAvgFps,\n        double MedianFrameP99Milliseconds,\n        double PrimaryRelativeSpread,\n        bool IsRankable,\n        string? Reason)\n    {\n        internal static CandidateEvaluation Unrankable(GpuAffinityCandidate candidate, string reason) =>\n            new(candidate, [], double.NegativeInfinity, double.NegativeInfinity, double.NegativeInfinity, double.PositiveInfinity, double.PositiveInfinity, false, reason);\n    }\n\n    private sealed record OriginalEvaluation(\n        double MedianLow1Fps,\n        double MedianLow01Fps,\n        double MedianAvgFps,\n        double MedianFrameP99Milliseconds,\n        double PrimaryRelativeSpread,\n        bool IsRankable,\n        string? Reason)\n    {\n        internal static OriginalEvaluation Unrankable(string reason) =>\n            new(double.NegativeInfinity, double.NegativeInfinity, double.NegativeInfinity, double.PositiveInfinity, double.PositiveInfinity, false, reason);\n    }\n'''
    new_records = '''    private sealed record CandidateEvaluation(\n        GpuAffinityCandidate Candidate,\n        GpuAutoAffinityTrialObservation[] Observations,\n        double MedianLow1Fps,\n        double MedianLow01Fps,\n        double MedianAvgFps,\n        double MedianFrameP99Milliseconds,\n        double PrimaryRelativeNoise,\n        int ValidObservationCount,\n        int TotalObservationCount,\n        bool IsRankable,\n        string? Reason)\n    {\n        internal static CandidateEvaluation Unrankable(\n            GpuAffinityCandidate candidate,\n            string reason,\n            int totalObservationCount = 0) =>\n            new(\n                candidate,\n                [],\n                double.NegativeInfinity,\n                double.NegativeInfinity,\n                double.NegativeInfinity,\n                double.PositiveInfinity,\n                double.PositiveInfinity,\n                0,\n                totalObservationCount,\n                false,\n                reason);\n    }\n\n    private sealed record OriginalEvaluation(\n        double MedianLow1Fps,\n        double MedianLow01Fps,\n        double MedianAvgFps,\n        double MedianFrameP99Milliseconds,\n        double PrimaryRelativeNoise,\n        int ValidObservationCount,\n        int TotalObservationCount,\n        bool IsRankable,\n        string? Reason)\n    {\n        internal static OriginalEvaluation Unrankable(string reason, int totalObservationCount) =>\n            new(\n                double.NegativeInfinity,\n                double.NegativeInfinity,\n                double.NegativeInfinity,\n                double.PositiveInfinity,\n                double.PositiveInfinity,\n                0,\n                totalObservationCount,\n                false,\n                reason);\n    }\n'''
    text = replace_once(text, old_records, new_records, "evaluation records")
    write(session_path, text)

    helper = '''namespace LatencyPilot.Benchmarking.Optimization;\n\ninternal sealed record GpuRepeatabilityClusterSelection(\n    int[] Indexes,\n    double Median,\n    double MaximumRelativeDeviation,\n    double TotalRelativeDeviation);\n\ninternal static class GpuRepeatabilityClusterSelector\n{\n    internal const int RequiredRunCount = 3;\n    internal const int MaximumAttemptCount = 5;\n    internal const double RelativeTolerance = 0.03d;\n\n    internal static GpuRepeatabilityClusterSelection? Select(IReadOnlyList<double> values)\n    {\n        ArgumentNullException.ThrowIfNull(values);\n        if (values.Count < RequiredRunCount ||\n            values.Any(static value => !double.IsFinite(value) || value <= 0d))\n        {\n            return null;\n        }\n\n        GpuRepeatabilityClusterSelection? best = null;\n        for (var first = 0; first < values.Count - 2; first++)\n        {\n            for (var second = first + 1; second < values.Count - 1; second++)\n            {\n                for (var third = second + 1; third < values.Count; third++)\n                {\n                    var indexes = new[] { first, second, third };\n                    var ordered = indexes.Select(index => values[index]).Order().ToArray();\n                    var median = ordered[1];\n                    var deviations = indexes\n                        .Select(index => Math.Abs(values[index] - median) / median)\n                        .ToArray();\n                    var maximum = deviations.Max();\n                    if (maximum > RelativeTolerance)\n                    {\n                        continue;\n                    }\n\n                    var total = deviations.Sum();\n                    if (best is null ||\n                        maximum < best.MaximumRelativeDeviation - 1e-12 ||\n                        (Math.Abs(maximum - best.MaximumRelativeDeviation) <= 1e-12 &&\n                         total < best.TotalRelativeDeviation - 1e-12))\n                    {\n                        best = new GpuRepeatabilityClusterSelection(indexes, median, maximum, total);\n                    }\n                }\n            }\n        }\n\n        return best;\n    }\n}\n'''
    write("src/LatencyPilot.Benchmarking/Optimization/GpuRepeatabilityClusterSelector.cs", helper)

