    new_start = '''            if (request.RetryAttempt > 0)\n            {\n                totalUnits = checked(totalUnits + 1);\n            }\n            else if (string.Equals(request.Phase, "screening-original", StringComparison.Ordinal))\n            {\n                originalScoredPassesStarted++;\n                if (originalScoredPassesStarted > GpuRepeatabilityClusterSelector.RequiredRunCount)\n                {\n                    totalUnits = checked(totalUnits + 1);\n                }\n            }\n            else if (string.Equals(request.Phase, "screening-finalists-warmup", StringComparison.Ordinal) &&\n                     request.Candidate is not null)\n            {\n                var key = request.Candidate.Processor.ToString();\n                finalistWarmupsStarted.TryGetValue(key, out var pass);\n                pass++;\n                finalistWarmupsStarted[key] = pass;\n                if (pass > 2)\n                {\n                    totalUnits = checked(totalUnits + 2);\n                }\n            }\n\n            var (candidateIndex, candidateCount) = GetCandidateOrdinal(request.Phase, request.Candidate);\n'''
    progress = replace_once(progress, old_start, new_start, "progress dynamic totals")

    warmup_anchor = '''        if (request.Phase.EndsWith("-warmup", StringComparison.Ordinal))\n        {\n            return request.Candidate is null\n                ? "Original-state benchmark warm-up/reference; not scored."\n                : "Post-affinity warm-up on the requested CPU; not scored.";\n        }\n'''
    warmup_replacement = '''        if (string.Equals(request.Phase, "screening-original", StringComparison.Ordinal))\n        {\n            return $"Original repeatability sample {originalScoredPassesStarted}; target 3 stable samples, maximum {GpuRepeatabilityClusterSelector.MaximumAttemptCount} attempts.";\n        }\n\n        if (request.Phase.EndsWith("-warmup", StringComparison.Ordinal))\n        {\n            return request.Candidate is null\n                ? "Original-state benchmark warm-up/reference; not scored."\n                : "Post-affinity warm-up on the requested CPU; not scored.";\n        }\n'''
    progress = replace_once(progress, warmup_anchor, warmup_replacement, "progress original sample text")

